//! Developer MeasurementSet fixtures generated by the current [`crate::Simulator`].
//! The typed sky/array inputs are shared by imaging/storage tests and the
//! `synthetic-ms` staging tool. Prediction, corruptions and MS writing have
//! one owner: the native simulator session.
mod family;
mod model;
mod spec;
pub mod task;
pub use spec::*;

use crate::{
    ArrayConfig, BackendRequest, CoordinateSystem, ExecutionControls, ObserveSpec,
    SessionResources, Simulator, SimulatorError, SimulatorOptions, SpectralWindowSpec, StateSpec,
};
use casa_core::measures::{
    EpochRef, MEpoch,
    direction::{DirectionRef, MDirection},
    frequency::FrequencyRef,
};
use casa_ms::MeasurementSet;
use serde::{Deserialize, Serialize};
use std::{num::NonZeroUsize, path::PathBuf, time::Instant};

/// A fixture preparation or simulator failure.
pub type Result<T> = crate::SimulatorResult<T>;
fn error(value: impl std::fmt::Display) -> SimulatorError {
    SimulatorError::raised(format!("synthetic fixture: {value}"))
}

/// Persisted fixture dimensions and measured total generation time.
#[derive(Debug, Clone, PartialEq, schemars::JsonSchema, Serialize, Deserialize)]
pub struct Report {
    /// Generated MeasurementSet.
    pub output_ms: PathBuf,
    /// MAIN rows written by the simulator.
    pub main_row_count: usize,
    /// Rows flagged by the native elevation/shadowing policy.
    pub flagged_row_count: usize,
    /// End-to-end wall time; includes model preparation and final persistence.
    pub elapsed_seconds: f64,
}

/// Build one fixture using the native simulator API.
///
/// # Errors
/// Invalid inputs, protected output, native prediction/corruption failure or I/O.
pub fn generate(request: &ObservationRequest) -> Result<Report> {
    run(request, false)
}

/// Build an unflagged fixture with native observing cuts disabled.
/// Storage and namespace tests supply their own flag patterns after creation.
///
/// # Errors
/// The same preparation, simulation and persistence failures as [`generate`].
pub fn generate_unflagged(request: &ObservationRequest) -> Result<Report> {
    run(request, true)
}

fn run(request: &ObservationRequest, unflagged: bool) -> Result<Report> {
    let started = Instant::now();
    request.polarization_setup.validate()?;
    if request.antennas.is_empty()
        || request.spectral_windows.is_empty()
        || !request.duration_seconds.is_finite()
        || request.duration_seconds <= 0.
        || !request.integration_seconds.is_finite()
        || request.integration_seconds <= 0.
    {
        return Err(error(
            "need antennas, windows and positive finite observing times",
        ));
    }
    if request.output_ms.exists() {
        if !request.overwrite {
            return Err(error("output MeasurementSet already exists"));
        }
        std::fs::remove_dir_all(&request.output_ms).map_err(error)?;
    }
    let resources = SessionResources::from_controls(&ExecutionControls {
        workers: request
            .row_workers
            .into_iter()
            .chain(request.channel_workers)
            .min()
            .and_then(NonZeroUsize::new),
        backend: BackendRequest::Cpu,
        ..ExecutionControls::default()
    })?;
    let mut sm = Simulator::open(
        &request.output_ms,
        SimulatorOptions::from_system(resources)?,
    );
    sm.set_config(&ArrayConfig {
        telescope: request.telescope_name.clone(),
        x: request.antennas.iter().map(|a| a.position_m[0]).collect(),
        y: request.antennas.iter().map(|a| a.position_m[1]).collect(),
        z: request.antennas.iter().map(|a| a.position_m[2]).collect(),
        dish_diameter: request.antennas.iter().map(|a| a.dish_diameter_m).collect(),
        offset: vec![0.],
        mount: vec!["ALT-AZ".into()],
        antenna_names: request.antennas.iter().map(|a| a.name.clone()).collect(),
        pad_names: request.antennas.iter().map(|a| a.station.clone()).collect(),
        coordinate_system: CoordinateSystem::Global,
    })?;
    sm.set_feed(
        match request.polarization_setup.basis {
            PolarizationBasis::Circular => "perfect R L",
            PolarizationBasis::Linear => "perfect X Y",
        },
        &[],
        &[],
        &[],
    )?;
    let stokes = match (
        request.polarization_setup.basis,
        request.polarization_setup.correlation_count,
    ) {
        (PolarizationBasis::Circular, 1) => "RR",
        (PolarizationBasis::Circular, 2) => "RR LL",
        (PolarizationBasis::Circular, _) => "RR RL LR LL",
        (PolarizationBasis::Linear, 1) => "XX",
        (PolarizationBasis::Linear, 2) => "XX YY",
        (PolarizationBasis::Linear, _) => "XX XY YX YY",
    };
    for window in &request.spectral_windows {
        sm.set_spectral_window(&SpectralWindowSpec {
            name: window.name.clone(),
            start_frequency_hz: window.start_frequency_hz,
            channel_width_hz: window.channel_width_hz,
            resolution_hz: window.channel_width_hz,
            frame: FrequencyRef::LSRK,
            channel_count: window.channel_count,
            stokes: stokes.into(),
        })?;
    }
    let fields = if request.fields.is_empty() {
        vec![Field {
            name: request.field_name.clone(),
            phase_center_rad: request.phase_center_rad,
        }]
    } else {
        request.fields.clone()
    };
    sm.set_times(
        request.integration_seconds,
        false,
        MEpoch::from_mjd(request.start_time_mjd_seconds / 86_400., EpochRef::UTC),
    )?;
    for field in &fields {
        sm.set_field(
            &field.name,
            &MDirection::from_angles(
                field.phase_center_rad[0],
                field.phase_center_rad[1],
                DirectionRef::J2000,
            ),
            "",
            0.,
        )?;
    }
    sm.set_limits(
        if unflagged { 1. } else { 0.001 },
        if unflagged || request.allow_below_elevation_limit {
            -std::f64::consts::FRAC_PI_2
        } else {
            request.elevation_limit_rad
        },
    );
    if request.observation_mode == ObservationMode::TotalPower && request.antennas.len() != 1 {
        return Err(error("a total-power fixture selects exactly one antenna"));
    }
    sm.set_auto(if request.observation_mode == ObservationMode::TotalPower {
        1.
    } else {
        0.
    });
    let samples = (request.duration_seconds / request.integration_seconds).ceil() as usize;
    for sample in 0..samples {
        let field = &fields[sample % fields.len()];
        for window in &request.spectral_windows {
            sm.observe(&ObserveSpec {
                source: field.name.clone(),
                spectral_window: window.name.clone(),
                start_s: sample as f64 * request.integration_seconds,
                stop_s: (sample + 1) as f64 * request.integration_seconds,
                add_observation: false,
                observer: request.observer.clone(),
                project: request.project.clone(),
                state: StateSpec {
                    sig: true,
                    reference: false,
                    cal: 0.,
                    load: 0.,
                    sub_scan: 0,
                    obs_mode: "OBSERVE_TARGET#ON_SOURCE".into(),
                },
            })?;
        }
    }
    let staging = tempfile::tempdir().map_err(error)?;
    if request.predict_model {
        model::predict(request, &mut sm, staging.path(), resources)?;
    }
    if let Some(corruption) = &request.corruption {
        sm.set_seed(corruption.seed as i32);
        if let Some(noise) = &corruption.noise {
            if noise.mode != NoiseMode::SimpleNoise {
                return Err(error(
                    "fixture noise requires simplenoise; use Simulator::set_noise for a configured Tsys atmosphere",
                ));
            }
            sm.set_noise(&crate::NoiseSpec {
                simple_noise_jy: f64::from(noise.simplenoise_jy),
                ..crate::NoiseSpec::default()
            })?;
        }
        if let Some(gain) = &corruption.gain {
            sm.set_gain(&crate::GainSpec {
                mode: match gain.mode {
                    GainMode::Fbm => "fbm",
                    GainMode::Random => "random",
                }
                .into(),
                table: String::new(),
                amplitude: gain.amplitude.map(f64::from).to_vec(),
            })?;
        }
        if let Some(leakage) = &corruption.leakage {
            sm.set_leakage(&crate::LeakageSpec {
                table: String::new(),
                amplitude: leakage.amplitude.map(f64::from).to_vec(),
                offset: leakage.offset.map(f64::from).to_vec(),
            })?;
        }
        sm.corrupt()?;
    }
    sm.close()?;
    let ms = MeasurementSet::open(&request.output_ms).map_err(error)?;
    let main_row_count = ms.row_count();
    let mut flagged_row_count = 0;
    for row in 0..main_row_count {
        if matches!(
            ms.main_table()
                .cell_accessor(row, "FLAG_ROW")
                .map_err(error)?
                .scalar()
                .map_err(error)?,
            casa_core::ScalarValue::Bool(true)
        ) {
            flagged_row_count += 1;
        }
    }
    Ok(Report {
        output_ms: request.output_ms.clone(),
        main_row_count,
        flagged_row_count,
        elapsed_seconds: started.elapsed().as_secs_f64(),
    })
}
